import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // === Plane Geometry & Material ===
  const PLANE_WIDTH = 1.6; // based on atlas aspect 512/320 = 1.6
  const PLANE_HEIGHT = 1.0;
  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT);
  const material = new MeshBasicNodeMaterial();
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously (function stays synchronous)
  const imageUrl = config.imageUrl ?? config.meshUrl ?? null;
  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // === Text Content ===
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // centre text on the plane, slightly offset forward to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // === Cinematic Primitives (none in this spec) ===
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const instance = fn(root, prim.params);
        primitiveInstances.push(instance);
      }
    }
  }

  // === Event Handlers (none defined) ===
  root.userData.handlers = {};

  // === Cleanup ===
  root.userData.cleanup = () => {
    // dispose geometry & material
    geometry.dispose();
    material.dispose();

    // dispose texture if it was loaded
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // dispose text objects (they may hold resources internally)
    for (const txt of textObjects) {
      if (txt.geometry && txt.geometry.dispose) txt.geometry.dispose();
      if (txt.material && txt.material.dispose) txt.material.dispose();
    }

    // cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    }

    // kill any GSAP timelines that might have been created
    gsap.globalTimeline.clear();
  };

  return root;
}
